    @Test
    public void testGetCurrentName_WhenTokenIsStartObject_AndParentIsNull() throws Exception {
        TestableFilteringParserDelegate testDelegate = new TestableFilteringParserDelegate(mockParser, mockFilter);
        JsonStreamContext context = mock(JsonStreamContext.class);

        when(context.getParent()).thenReturn(null);
        testDelegate.setInternalState(context, JsonToken.START_OBJECT);

        String result = testDelegate.getCurrentName();
        assertNull("Should return null when parent context is null and token is START_OBJECT", result);
    }

    @Test
    public void testGetCurrentName_WhenTokenIsStartArray_AndParentExists() throws Exception {
        TestableFilteringParserDelegate testDelegate = new TestableFilteringParserDelegate(mockParser, mockFilter);
        JsonStreamContext parentContext = mock(JsonStreamContext.class);
        JsonStreamContext childContext = mock(JsonStreamContext.class);

        when(childContext.getParent()).thenReturn(parentContext);
        when(parentContext.getCurrentName()).thenReturn("parentName");
        testDelegate.setInternalState(childContext, JsonToken.START_ARRAY);

        String result = testDelegate.getCurrentName();
        assertEquals("Should return parent name when token is START_ARRAY", "parentName", result);
    }

