        TestableFilteringParserDelegate testDelegate = new TestableFilteringParserDelegate(mockParser, mockFilter);
        JsonStreamContext parentContext = mock(JsonStreamContext.class);
        JsonStreamContext childContext = mock(JsonStreamContext.class);

        when(childContext.getParent()).thenReturn(parentContext);
        when(parentContext.getCurrentName()).thenReturn("objectKey");
        testDelegate.setInternalState(childContext, JsonToken.START_OBJECT);

        String result = testDelegate.getCurrentName();
        assertEquals("Should return parent name when token is START_OBJECT", "objectKey", result);
